import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to;
        int time;
        int cost;

        Edge(int to, int time, int cost) {
            this.to = to;
            this.time = time;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        int node;
        int cost;
        long time;

        State(int node, int cost, long time) {
            this.node = node;
            this.cost = cost;
            this.time = time;
        }

        @Override
        public int compareTo(State other) {
            return Long.compare(this.time, other.time);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int V = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        List<Edge>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());
            int p = Integer.parseInt(st.nextToken());

            adj[a].add(new Edge(b, t, p));
            adj[b].add(new Edge(a, t, p));
        }

        st = new StringTokenizer(br.readLine());
        int X = Integer.parseInt(st.nextToken());
        int Y = Integer.parseInt(st.nextToken());

        final long INF = Long.MAX_VALUE / 4;
        long[][] dist = new long[N + 1][V + 1];

        for (int i = 1; i <= N; i++) {
            Arrays.fill(dist[i], INF);
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[X][0] = 0;
        pq.add(new State(X, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();

            if (cur.time != dist[cur.node][cur.cost]) continue;

            if (cur.node == Y) {
                System.out.println(cur.time);
                return;
            }

            for (Edge e : adj[cur.node]) {
                int nextCost = cur.cost + e.cost;

                if (nextCost > V) continue;

                long nextTime = cur.time + e.time;

                if (nextTime < dist[e.to][nextCost]) {
                    dist[e.to][nextCost] = nextTime;
                    pq.add(new State(e.to, nextCost, nextTime));
                }
            }
        }

        System.out.println(-1);
    }
}
